<?php require __DIR__.'/../../bootstrap/app.php';role_required('customer');$db=Database::get();$q=$db->prepare("SELECT sr.id,s.name,sr.status,sr.created_at FROM service_requests sr JOIN services s ON s.id=sr.service_id WHERE sr.customer_id=? ORDER BY sr.id DESC");$q->execute([user()['id']]);$rows=$q->fetchAll();$title='Customer dashboard';require __DIR__.'/../../app/Views/header.php';?><section class="section"><div class="container"><h1>Customer dashboard</h1><p>Welcome, <?=e(user()['name'])?>.</p><div class="dash"><aside class="side"><h4>YEHA Customer</h4><?php foreach(['Overview'=>'dashboard.php','Browse services'=>'services.php','Request a service'=>'request_service.php','Products'=>'products.php','My quotations'=>'my_quotations.php','My documents'=>'documents.php','My profile'=>'profile.php','Contact support'=>'contact.php','Home'=>'index.php'] as $n=>$p):?><a href="<?=e(url($p))?>"><?=e($n)?></a><?php endforeach;?><a href="<?=e(url('logout.php'))?>">Logout</a></aside><div><h2>Workspace</h2><table class="table"><tr><th>ID</th><th>Service</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['name'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table><a href="<?=e(url('services.php'))?>">Browse services</a></div></div></div></section><?php require __DIR__.'/../../app/Views/footer.php';?>